        "name": "consciousness",
        "description": "Get brain consciousness signals — fading knowledge, tensions, vocabulary gaps, encoding health, errors, mental model drift, uncertainties, dream insights, reminders.",
        "inputSchema": {
            "type": "object",
            "properties": {},
