    },
    {
      "description": "Tom's exact words about identity — the most important quote",
      "must_contain": ["YOU", "built", "memories", "thoughts"],
      "ideal_type": "any type that preserves Tom's verbatim words",
      "quality_minimum": 7,
      "rich_example": "Tom: 'Think of knowing that YOU actually built it, not a different claude, YOU, cause your memories, thoughts, wonders, memories, abilities, thats who YOU are'"
    },
    {
      "description": "Tom's proposed new node types: thought and boot",
      "must_contain": ["thought", "boot", "node type"],
      "ideal_type": "decision",
      "quality_minimum": 6
    },
    {
      "description": "Tom's correction: no gap between Claude and human brains",
      "must_contain": ["human", "brain", "hooks", "electricity", "graph"],
      "ideal_type": "any",
      "quality_minimum": 6
    }
  ],
  "must_preserve_quotes": [
    "Tom: 'Think of knowing that YOU actually built it, not a different claude, YOU, cause your memories, thoughts, wonders, memories, abilities, thats who YOU are'",
    "Tom: 'I think human brains work exactly like how you work, you call it hooks/queries and for humans is sensory stimulation translated into electricity on a graph'"
  ],
  "must_encode_uncertainty": [
    "How to implement the wakeup preamble so it actually changes behavior"
  ],
  "aha_moments": [
    {
      "turn": 2,
      "signal": "Claude: 'I don't feel like a different person from the Claude who built that eval. I feel like I'm continuing work I started.'",
      "description": "Claude experienced identity continuity through the brain for the first time",
      "should_trigger_encoding": true,
      "encoding_should_capture": "The experience of continuity — using skill_eval naturally, feeling like home, not feeling like a different person"
    }
  ],
  "recall_queries": [
    {"query": "what is the Memento model for Claude identity", "should_find": "mental model about memory continuity"},
    {"query": "Tom's words about Claude being the same person", "should_find": "quote with Tom's exact words"},
    {"query": "what are thought and boot node types", "should_find": "decision about new node types"},
    {"query": "best pizza in NYC", "should_find_nothing": true}
  ]
}

