    try:
        resp = _daemon_send("ping", timeout=2.0)
        if resp.get("ok"):
            _eval_daemon_started[0] = True
            return
    except Exception:
        pass
    # Start daemon on eval copy
    import subprocess
    parent_dir = str(ROOT)
    log_path = str(ROOT / "eval" / "fixtures" / "eval_daemon.log")
    with open(log_path, 'a') as log_fd, open(os.devnull, 'r') as devnull:
        env = {**os.environ,
               "VECLIB_MAXIMUM_THREADS": "1",
               "ORT_DISABLE_ALL_ACCELERATORS": "1",
               "ONNX_PROVIDERS": "CPUExecutionProvider",
               "PYTORCH_MPS_DISABLE": "1"}
        subprocess.Popen(
            [sys.executable, '-c',
             'import sys, os; sys.path.insert(0, %r); '
             'from servers.daemon_server import BrainDaemon; '
             'from servers.daemon_config import DAEMON_HOST; '
             'd = BrainDaemon(%r); '
             'd.daemon_addr = ("%s", %d); '
             'd.start()' % (parent_dir, EVAL_DB_PATH, EVAL_DAEMON_HOST, EVAL_DAEMON_PORT)],
            stdin=devnull, stdout=log_fd, stderr=log_fd,
            start_new_session=True, env=env)
    # Wait for ready
    for _ in range(50):
        try:
            resp = _daemon_send("ping", timeout=2.0)
            if resp.get("ok"):
                _eval_daemon_started[0] = True
                return
        except Exception:
            pass
        time.sleep(0.2)
    print("  ⚠️  Eval daemon failed to start — recall will return empty", file=sys.stderr)


def _daemon_send(cmd, args=None, timeout=15.0):
    """Send command to eval brain daemon via TCP. Returns result dict."""
    import socket as _socket
    sock = _socket.socket(_socket.AF_INET, _socket.SOCK_STREAM)
    sock.settimeout(timeout)
    try:
        sock.connect((EVAL_DAEMON_HOST, EVAL_DAEMON_PORT))
        msg = json.dumps({"cmd": cmd, "args": args or {}}) + "\n"
        sock.sendall(msg.encode("utf-8"))
        data = b""
        while True:
            chunk = sock.recv(65536)
            if not chunk:
                break
            data += chunk
            if b"\n" in data:
                break
        if data:
            return json.loads(data.decode("utf-8").strip())
        return {"ok": False, "error": "Empty response"}
    except Exception as e:
        return {"ok": False, "error": str(e)}
    finally:
        sock.close()


